#[derive(Clone)]struct Relation{row:usize,form:Form,a:Form,b:Form,c:Form}
fn put(m:&mut BTreeMap<usize,Fr>,w:usize,c:Fr){let x=m.entry(w).or_insert(Fr::ZERO);*x+=c;if *x==Fr::ZERO{m.remove(&w);}}
fn linearized(a:&Form,b:&Form,c:&Form,bits:&BTreeSet<usize>)->Option<Form>{
 let mut out=a.scale(b.constant).plus(&b.scale(a.constant));out.constant=a.constant*b.constant;out=out.minus(c);let mut quadratic=BTreeMap::<(usize,usize),Fr>::new();
 for(&i,&x)in&a.terms{for(&j,&y)in&b.terms{let product=x*y;if i==j&&bits.contains(&i){put(&mut out.terms,i,product)}else{let pair=if i<=j{(i,j)}else{(j,i)};let q=quadratic.entry(pair).or_insert(Fr::ZERO);*q+=product;if *q==Fr::ZERO{quadratic.remove(&pair);}}}}
 quadratic.is_empty().then_some(out)
}
fn serial(f:&Form)->Vec<(usize,[u64;4])>{let mut v=vec![];if f.constant!=Fr::ZERO{v.push((0,f.constant.to_canonical()));}v.extend(f.terms.iter().map(|(&w,&c)|(w,c.to_canonical())));v}
fn normalized(f:&Form)->Vec<(usize,[u64;4])>{let x=if f.constant!=Fr::ZERO{f.constant}else{f.terms.values().next().copied().unwrap_or(Fr::ONE)};serial(&f.scale(x.inverse().unwrap()))}
fn rank(forms:&[Form],public:usize)->(usize,usize){let mut basis=BTreeMap::<usize,Form>::new();let mut public_residual=0;for f in forms{let mut f=f.clone();loop{let Some((&w,&c))=f.terms.range(public..).next_back()else{if !f.terms.is_empty()||f.constant!=Fr::ZERO{public_residual+=1;}break};if let Some(row)=basis.get(&w){f=f.minus(&row.scale(c));}else{basis.insert(w,f.scale(c.inverse().unwrap()));break}}}(basis.len(),public_residual)}
